     4→using System;
     5→using System.Diagnostics;
     6→using System.Diagnostics.CodeAnalysis;
     7→using System.IO;
     8→using Nethermind.Core;
     9→using Nethermind.Core.Eip2930;
    10→using Nethermind.Core.Extensions;
    11→using Nethermind.Core.Specs;
    12→using Nethermind.Int256;
    13→
    14→namespace Nethermind.Evm;
    15→
    16→
    17→public readonly record struct IntrinsicGas(long Standard, long FloorGas)
    18→{
    19→    public long MinimalGas { get; } = Math.Max(Standard, FloorGas);
    20→    public static explicit operator long(IntrinsicGas gas) => gas.MinimalGas;
    21→}
    22→
    23→public static class IntrinsicGasCalculator
    24→{
    25→    public static IntrinsicGas Calculate(Transaction transaction, IReleaseSpec releaseSpec)
    26→    {
    27→        var intrinsicGas = GasCostOf.Transaction
    28→               + DataCost(transaction, releaseSpec)
    29→               + CreateCost(transaction, releaseSpec)
    30→               + AccessListCost(transaction, releaseSpec)
    31→               + AuthorizationListCost(transaction, releaseSpec);
    32→        var floorGas = CalculateFloorCost(transaction, releaseSpec);
    33→        return new IntrinsicGas(intrinsicGas, floorGas);
    34→    }
    35→
    36→    private static long CreateCost(Transaction transaction, IReleaseSpec releaseSpec) =>
    37→        transaction.IsContractCreation && releaseSpec.IsEip2Enabled ? GasCostOf.TxCreate : 0;
    38→
    39→    private static long DataCost(Transaction transaction, IReleaseSpec releaseSpec)
    40→    {
    41→        long baseDataCost = transaction.IsContractCreation && releaseSpec.IsEip3860Enabled
    42→            ? EvmInstructions.Div32Ceiling((UInt256)transaction.Data.Length) *
    43→              GasCostOf.InitCodeWord
    44→            : 0;
    45→
    46→        long tokensInCallData = CalculateTokensInCallData(transaction, releaseSpec);
    47→
    48→        return baseDataCost + tokensInCallData * GasCostOf.TxDataZero;
    49→    }
    50→
    51→    public static long AccessListCost(Transaction transaction, IReleaseSpec releaseSpec)
    52→    {
    53→        AccessList? accessList = transaction.AccessList;
    54→        if (accessList is not null)
    55→        {
    56→            if (!releaseSpec.UseTxAccessLists)
    57→            {
    58→                ThrowInvalidDataException(releaseSpec);
    59→            }
    60→
    61→            (int addressesCount, int storageKeysCount) = accessList.Count;
    62→            return addressesCount * GasCostOf.AccessAccountListEntry + storageKeysCount * GasCostOf.AccessStorageListEntry;
    63→        }
    64→
    65→        return 0;
    66→
    67→        [DoesNotReturn, StackTraceHidden]
    68→        static void ThrowInvalidDataException(IReleaseSpec releaseSpec)
    69→        {
    70→            throw new InvalidDataException($"Transaction with an access list received within the context of {releaseSpec.Name}. EIP-2930 is not enabled.");
    71→        }
    72→    }
    73→
    74→    private static long AuthorizationListCost(Transaction transaction, IReleaseSpec releaseSpec)
    75→    {
    76→        AuthorizationTuple[]? transactionAuthorizationList = transaction.AuthorizationList;
    77→
    78→        if (transactionAuthorizationList is not null)
    79→        {
    80→            if (!releaseSpec.IsAuthorizationListEnabled)
    81→            {
    82→                ThrowInvalidDataException(releaseSpec);
    83→            }
    84→
    85→            return transactionAuthorizationList.Length * GasCostOf.NewAccount;
    86→        }
    87→
    88→        return 0;
